using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;
using BenchmarkDotNet.Jobs;
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Reports;
using TextAnalysis;

[SimpleJob(RuntimeMoniker.Net90)]
[SimpleJob(RuntimeMoniker.Net100)]
[MemoryDiagnoser]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    private const string SampleText =
        "The quick brown fox jumps over the lazy dog. " +
        "A wonderful serenity has taken possession of my entire soul. " +
        "I am alone and feel the charm of existence in this spot. " +
        "The quick brown fox jumps over the lazy dog again and again. " +
        "Programming is the art of telling another human what one wants the computer to do. " +
        "Software engineering is what happens to programming when you add time and other programmers.";

    [GlobalSetup]
    public void Setup()
    {
        _analyzer = new TextAnalyzer(SampleText);
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

public class Program
{
    public static void Main(string[] args)
    {
        BenchmarkRunner.Run<TextAnalyzerBenchmarks>(
            DefaultConfig.Instance
                .WithSummaryStyle(SummaryStyle.Default),
            args);
    }
}

